import React from "react";
import { Link } from "react-router-dom";
import "./Footer.css";

export default function Footer(){
  return (
    <footer style={{background:"#0f172a", color:"#fff", marginTop:40, padding:"36px 0"}}>
      <div className="container" style={{display:"flex", justifyContent:"space-between", gap:24, flexWrap:"wrap"}}>
        <div>
          <h3>HirePro</h3>
          <p style={{maxWidth:320}}>Find verified professionals for home services — plumbing, cleaning, beauty and more.</p>
        </div>
        <div>
          <h4>Company</h4>
          <Link to="/about" className="footer-link">About</Link><br/>
          <Link to="/terms" className="footer-link">Terms</Link><br/>
          <Link to="/privacy" className="footer-link">Privacy</Link>
        </div>
        <div>
          <h4>Support</h4>
          <Link to="/faq" className="footer-link">FAQ</Link><br/>
          <Link to="/contact" className="footer-link">Contact</Link>
        </div>
      </div>
    </footer>
  );
}
